await document.modelContext.registerTool({
  name: "add_to_route",
  description: "Add a reading",
  inputSchema: schema({
    articleId: {
      type: "string",
      enum: articles.map(a => a.id)
    }
  }),
  execute: add
});

// Inside execute: add (slide 7)
function add({ articleId }) {
  const article = articles.find(a => a.id === articleId);
  if (!article) {
    return {
      code: "UNKNOWN_ARTICLE",
      error: "Use: models, browserdj, patterns",
      retryable: true
    };
  }
  return saveToRoute(article);
}

